using Documents.Api.Data;using Documents.Api.Models;using Documents.Api.Services;using Microsoft.Data.Sqlite;using Microsoft.EntityFrameworkCore;
namespace Documents.Tests;
public sealed class DocumentServiceTests:IAsyncLifetime{readonly SqliteConnection c=new("Data Source=:memory:");DocumentsDbContext db=null!;DocumentService s=null!;public async Task InitializeAsync(){await c.OpenAsync();db=new(new DbContextOptionsBuilder<DocumentsDbContext>().UseSqlite(c).Options);await db.Database.EnsureCreatedAsync();db.Users.AddRange(new User{Id=1,Username="user",PasswordHash="x",Role="User"},new User{Id=2,Username="reviewer",PasswordHash="x",Role="Reviewer"});db.Documents.Add(new TrackedDocument{Id=1,TrackingNumber="DOC-1",Title="Request",Department="Finance",CreatedById=1});await db.SaveChangesAsync();s=new(db);}public async Task DisposeAsync(){await db.DisposeAsync();await c.DisposeAsync();}
[Fact]public async Task Owner_CanSubmitAndHistoryIsRecorded(){var d=await s.TransitionAsync(1,Statuses.Submitted,"ready",1,false);Assert.Single(d.Events);Assert.Equal(Statuses.Submitted,d.Status);}
[Fact]public async Task Owner_CannotReview(){await s.TransitionAsync(1,Statuses.Submitted,"",1,false);await Assert.ThrowsAsync<UnauthorizedAccessException>(()=>s.TransitionAsync(1,Statuses.InReview,"",1,false));}
[Fact]public async Task Reviewer_CanApproveThroughValidStates(){await s.TransitionAsync(1,Statuses.Submitted,"",1,false);await s.TransitionAsync(1,Statuses.InReview,"",2,true);var d=await s.TransitionAsync(1,Statuses.Approved,"ok",2,true);Assert.Equal(Statuses.Approved,d.Status);Assert.Equal(3,d.Events.Count);}
[Fact]public async Task InvalidTransition_IsRejected(){await Assert.ThrowsAsync<InvalidOperationException>(()=>s.TransitionAsync(1,Statuses.Approved,"",2,true));}
}
